import { boot } from 'quasar/wrappers';

// Make Quasar's QMenu (q-select, q-btn-dropdown, etc.) behave correctly when
// the page scrolls inside an inner container instead of the window.
//
// Quasar's QMenu auto-detects its scroll target by walking up from the anchor
// and matching the first element with class `.scroll`, `.scroll-y`, or
// `.overflow-auto` (node_modules/quasar/src/utils/scroll/scroll.js
// `getScrollTarget`). Our legacy page containers (`.page-height-limit`,
// `.height-100vh-*`, `.scroll-area-height-*`) use plain CSS `overflow-y: auto`
// without those marker classes, so QMenu falls back to `window`. Result:
// dropdowns drift away from their anchors when the inner container scrolls,
// and stay open after the anchor scrolls out of view.
//
// This boot file:
//   1. Tags every scrollable element with `scroll-y` so getScrollTarget
//      finds it. Quasar's `.scroll-y` rule sets `overflow-y: auto`
//      (matches what the element already had) plus `will-change:
//      scroll-position` (Quasar applies this to its own scroll areas
//      already, so no new behavior).
//   2. Watches each open `.q-menu` and closes it via the QSelect's exposed
//      `hidePopup()` method once the anchor leaves the visible viewport.

export function isScrollable(el: HTMLElement): boolean {
  const overflowY = getComputedStyle(el).overflowY;
  return overflowY === 'auto' || overflowY === 'scroll';
}

export function tagIfScrollable(el: HTMLElement) {
  if (el.classList.contains('scroll') || el.classList.contains('scroll-y') || el.classList.contains('overflow-auto')) {
    return;
  }
  if (isScrollable(el)) {
    el.classList.add('scroll-y');
  }
}

export function tagScope(root: ParentNode) {
  // Tag the root (if it's an element) plus everything under it. Scoping to
  // the added subtree instead of `document.querySelectorAll('*')` keeps
  // mutation-driven sweeps cheap on heavy pages (validation, line-item
  // tables) where the observer fires frequently.
  if (root instanceof HTMLElement) tagIfScrollable(root);
  root.querySelectorAll<HTMLElement>('*').forEach(tagIfScrollable);
}

const pendingRoots = new Set<ParentNode>();
let sweepScheduled = false;
function scheduleSweep(root: ParentNode) {
  pendingRoots.add(root);
  if (sweepScheduled) return;
  sweepScheduled = true;
  requestAnimationFrame(() => {
    sweepScheduled = false;
    const roots = Array.from(pendingRoots);
    pendingRoots.clear();
    roots.forEach(tagScope);
  });
}

export function getScrollTargets(el: HTMLElement): Array<HTMLElement | Window> {
  const out: Array<HTMLElement | Window> = [];
  for (let node: HTMLElement | null = el; node && node !== document.body; node = node.parentElement) {
    if (isScrollable(node) && node.scrollHeight > node.clientHeight) {
      out.push(node);
    }
  }
  out.push(window);
  return out;
}

export function isAnchorInView(anchor: HTMLElement, scrollableAncestors: HTMLElement[]): boolean {
  const aRect = anchor.getBoundingClientRect();
  if (aRect.bottom <= 0 || aRect.top >= window.innerHeight) return false;
  for (const node of scrollableAncestors) {
    const cRect = node.getBoundingClientRect();
    if (aRect.bottom <= cRect.top || aRect.top >= cRect.bottom) return false;
  }
  return true;
}

export function getMenuAnchor(menuEl: HTMLElement): HTMLElement | null {
  if (!menuEl.id) return null;
  const controller = document.querySelector<HTMLElement>(`[aria-controls="${menuEl.id}"]`);
  if (!controller) return null;
  return (controller.closest('.q-field') as HTMLElement) || controller;
}

export function hidePopupFor(menuEl: HTMLElement) {
  // Walk up from the controller through Vue's component-instance chain
  // (Vue 3 attaches `__vueParentComponent` to DOM nodes) and call the
  // first `hidePopup()` we find — QSelect exposes this on its proxy.
  // Using the public method avoids dispatching synthetic key events,
  // which would bubble to the app's global Escape handler.
  const controller = document.querySelector<HTMLElement>(`[aria-controls="${menuEl.id}"]`);
  if (!controller) return;
  for (let node: HTMLElement | null = controller; node; node = node.parentElement) {
    const root = (node as any).__vueParentComponent;
    for (let cmp = root; cmp; cmp = cmp.parent) {
      const proxy = cmp.exposed || cmp.proxy;
      if (proxy && typeof proxy.hidePopup === 'function') {
        proxy.hidePopup();
        return;
      }
    }
  }
}

const watchers = new WeakMap<HTMLElement, () => void>();

function watchMenu(menuEl: HTMLElement) {
  if (watchers.has(menuEl)) return;
  // Anchor wiring happens after mount — defer one frame.
  requestAnimationFrame(() => {
    if (!menuEl.isConnected) return;
    const anchor = getMenuAnchor(menuEl);
    if (!anchor) return;
    const targets = getScrollTargets(anchor);
    const ancestors = targets.filter((t): t is HTMLElement => t !== window);

    let closed = false;
    const onScroll = () => {
      if (closed || !menuEl.isConnected) return;
      if (!isAnchorInView(anchor, ancestors)) {
        closed = true;
        hidePopupFor(menuEl);
      }
    };
    const opts: AddEventListenerOptions = { passive: true, capture: true };
    targets.forEach((t) => t.addEventListener('scroll', onScroll, opts));
    watchers.set(menuEl, () => targets.forEach((t) => t.removeEventListener('scroll', onScroll, opts)));
  });
}

function unwatchMenu(menuEl: HTMLElement) {
  const cleanup = watchers.get(menuEl);
  if (cleanup) {
    cleanup();
    watchers.delete(menuEl);
  }
}

function forEachMenu(node: HTMLElement, fn: (m: HTMLElement) => void) {
  if (node.classList.contains('q-menu')) fn(node);
  node.querySelectorAll<HTMLElement>('.q-menu').forEach(fn);
}

export default boot(() => {
  if (typeof window === 'undefined' || typeof document === 'undefined') return;

  const initialSweep = () => scheduleSweep(document);
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initialSweep, { once: true });
  } else {
    initialSweep();
  }

  const observer = new MutationObserver((mutations) => {
    for (const m of mutations) {
      m.addedNodes.forEach((node) => {
        if (!(node instanceof HTMLElement)) return;
        forEachMenu(node, watchMenu);
        scheduleSweep(node);
      });
      m.removedNodes.forEach((node) => {
        if (!(node instanceof HTMLElement)) return;
        forEachMenu(node, unwatchMenu);
      });
    }
  });
  observer.observe(document.body, { childList: true, subtree: true });
});
